1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededException;
9	import org.springframework.samples.petclinic.util.BusinessDays;
10	
11	/**
12	 * Rejects a create request once {@link #DAILY_LIMIT} or more owners have already been
13	 * registered today (by {@code registrationDate}). Runs before the owner is built, so the
14	 * count reflects the owners that already exist. Reported as a 429 by
15	 * {@link org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededExceptionHandler}.
16	 */
17	public class RequireDailyLimit {
18	
19	    static final int DAILY_LIMIT = 100;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DailyLimitExceededException {
23	        // Count against the effective registration date for this request, rolled forward
24	        // to a business day exactly as BuildOwner will store it, so the limit is per
25	        // adjusted business day (a weekend request counts toward the following Monday).
26	        LocalDate supplied = request.getRegistrationDate();
27	        LocalDate effective = BusinessDays.toBusinessDay(supplied == null ? LocalDate.now() : supplied);
28	        long count = ownerRepository.findAll().stream()
29	            .filter(existing -> effective.equals(existing.getRegistrationDate()))
30	            .count();
31	        if (count >= DAILY_LIMIT) {
32	            throw new DailyLimitExceededException(DAILY_LIMIT);
33	        }
34	    }
35	}
