1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Rejects a create request whose derived {@code identityKey} exactly equals an existing
11	 * owner's. This single check consolidates the former separate telephone, email and
12	 * household duplicate checks: all three are now expressed through one key
13	 * ({@link IdentityKeys}). Because the telephone is part of the key, two owners that differ
14	 * in any of telephone, email or household have different keys and are both allowed — only a
15	 * WHOLE-key match is a conflict, reported as a 409 by
16	 * {@link org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityExceptionHandler}.
17	 */
18	public class RequireUniqueIdentity {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateIdentityException {
22	        String identityKey = IdentityKeys.forRequest(request);
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (identityKey.equals(IdentityKeys.forOwner(existing))) {
25	                throw new DuplicateIdentityException(identityKey);
26	            }
27	        }
28	    }
29	}
