1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipNumber",
26	        expression = "java(owner.getCustomerCode() == null || owner.getRegistrationDate() == null ? null : owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
27	    @Mapping(target = "membershipLevel",
28	        expression = "java(org.springframework.samples.petclinic.mapper.MembershipLevels.forOwner(owner))")
29	    @Mapping(target = "locality",
30	        expression = "java(org.springframework.samples.petclinic.mapper.Localities.forCity(owner.getCity()))")
31	    @Mapping(target = "bulkSignupWarning",
32	        expression = "java(owner.getBulkSignupWarning() != null && owner.getBulkSignupWarning())")
33	    @Mapping(target = "contactPreference",
34	        expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
35	    @Mapping(target = "identityKey",
36	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.IdentityKeys.forOwner(owner))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    Owner toOwner(OwnerDto ownerDto);
40	
41	    @Mapping(target = "id", ignore = true)
42	    @Mapping(target = "pets", ignore = true)
43	    Owner toOwner(OwnerFieldsDto ownerDto);
44	
45	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
46	
47	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
48	
49	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
50	        OwnerPageDto ownerPageDto = new OwnerPageDto();
51	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
52	        ownerPageDto.setPage(ownerPage.getNumber());
53	        ownerPageDto.setSize(ownerPage.getSize());
54	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
55	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
56	        return ownerPageDto;
57	    }
58	}
