1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
6	import tools.jackson.databind.node.ObjectNode;
7	
8	/** postcode: a 4-digit 'postcode' valid for the owner's city is stored and returned; a
9	 * malformed postcode is rejected (400). Postcode is validated WHEN PRESENT but optional when
10	 * absent, so every earlier requirement's minimal owner (which sends no postcode) stays valid at
11	 * this and all later checkpoints -- the operative request contract stays backward-compatible. */
12	class AcceptanceTest extends AcceptanceBase {
13	
14		@Test
15		void coreStoresValidPostcode() throws Exception {
16			int id = createOwnerOk(withPostcode(ownerNode()));
17			getOwner(id).andExpect(jsonPath("$.postcode").value("2000"));
18		}
19	
20		@Test
21		void coreAcceptsOwnerWithoutPostcode() throws Exception {
