9	/**
10	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}
11	 * where CITY3 is the upper-cased first three letters of city, LAST3 the upper-cased
12	 * first three letters of lastName, and NNNN a per-city 4-digit zero-padded sequence
13	 * equal to one more than the owners already in that city (e.g. {@code SYD-SMI-0007}).
14	 * Runs before the owner is saved, so the count reflects the owners that already exist.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String city3 = prefix(owner.getCity());
20	        String last3 = prefix(owner.getLastName());
21	        String city = owner.getCity();
22	        long sequence = ownerRepository.findAll().stream()
23	            .filter(existing -> city == null ? existing.getCity() == null : city.equals(existing.getCity()))
24	            .count() + 1L;
25	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
26	    }
27	
28	    private static String prefix(String value) {
29	        int end = Math.min(3, value.length());
30	        return value.substring(0, end).toUpperCase(Locale.ROOT);
31	    }
32	}
