1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Canonicalises a free-text street address so it is stored, returned and compared in a
8	 * single form. Normalization: trim and collapse runs of whitespace to a single space,
9	 * upper-case, and expand common street-type abbreviations token-by-token
10	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
11	 *
12	 * <p>The transform is idempotent, so applying it to an already-normalized address (e.g.
13	 * one read back from an existing owner) yields the same value.
14	 */
15	final class AddressNormalizer {
16	
17	    /** Upper-cased abbreviation -> its expansion. */
18	    private static final Map<String, String> ABBREVIATIONS = Map.of(
19	            "ST", "STREET",
20	            "RD", "ROAD",
21	            "AVE", "AVENUE");
22	
23	    private AddressNormalizer() {
24	    }
25	
26	    /**
27	     * @return the normalized address, or {@code ""} when {@code value} is {@code null} or
28	     *         blank after trimming.
29	     */
30	    static String normalize(String value) {
31	        if (value == null) {
32	            return "";
33	        }
34	        String trimmed = value.trim();
35	        if (trimmed.isEmpty()) {
36	            return "";
37	        }
38	        String[] tokens = trimmed.toUpperCase(Locale.ROOT).split("\\s+");
39	        StringBuilder sb = new StringBuilder();
40	        for (String token : tokens) {
41	            if (sb.length() > 0) {
42	                sb.append(' ');
43	            }
44	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
45	        }
46	        return sb.toString();
47	    }
48	}
