1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Computes an owner's {@code identityKey}: the single derived value all duplicate detection
8	 * is expressed through. The key is
9	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
10	 *
11	 * <p>Two owners are duplicates only when their WHOLE keys are equal (see
12	 * {@link RequireUniqueIdentity}). Because the telephone is part of the key, two members of
13	 * the same household (same {@code householdId}) with different telephones have different
14	 * keys and are both allowed; only an exact full-key match is a conflict.
15	 *
16	 * <ul>
17	 * <li>telephone is normalized to E.164 form ({@link Telephones#toE164(String)}),
18	 * <li>email is trimmed and lower-cased, contributing empty when absent,
19	 * <li>householdId is the owner's shared-household identifier, empty when the owner is not
20	 *     part of a shared household.
21	 * </ul>
22	 */
23	public final class IdentityKeys {
24	
25	    private IdentityKeys() {
26	    }
27	
28	    /** The identity key of an existing owner, from its stored fields. */
29	    public static String forOwner(Owner owner) {
30	        return build(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
31	    }
32	
33	    /** The prospective identity key of an incoming create request. */
34	    public static String forRequest(OwnerFieldsDto request) {
35	        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
36	                ? Households.idFor(request.getLastName(), request.getAddress())
37	                : null;
38	        return build(request.getTelephone(), request.getEmail(), householdId);
39	    }
40	
41	    private static String build(String telephone, String email, String householdId) {
42	        String tel = Telephones.toE164(telephone);
43	        return (tel == null ? "" : tel) + "|" + normalizeEmail(email) + "|"
44	                + (householdId == null ? "" : householdId);
45	    }
46	
47	    /** Trim and lower-case; null or blank yields empty (no email to contribute). */
48	    private static String normalizeEmail(String email) {
49	        if (email == null || email.isBlank()) {
50	            return "";
51	        }
52	        return email.trim().toLowerCase();
53	    }
54	}
