1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Derives the stable {@code householdId} shared by owners who live together at the same
9	 * address. The id is the {@link #hash(String) SHA-256 prefix} of the normalized last name
10	 * and address, so every owner sharing a household (same normalized last name + address)
11	 * maps to the same value.
12	 *
13	 * <p>Centralising the derivation here keeps {@link AssignHousehold} (which assigns the id)
14	 * and {@link IdentityKeys} (which folds it into an owner's identity key) in exact agreement.
15	 */
16	public final class Households {
17	
18	    private Households() {
19	    }
20	
21	    /** The stable {@code householdId} for the given last name and address. */
22	    public static String idFor(String lastName, String address) {
23	        return hash(normalize(lastName) + "|" + AddressNormalizer.normalize(address));
24	    }
25	
26	    /** Lower-case, trim, and collapse runs of whitespace to a single space. */
27	    public static String normalize(String value) {
28	        if (value == null) {
29	            return "";
30	        }
31	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
32	    }
33	
34	    /** Stable 16-hex-character (upper-case) prefix of the SHA-256 of the household key. */
35	    private static String hash(String value) {
36	        try {
37	            byte[] digest = MessageDigest.getInstance("SHA-256")
38	                    .digest(value.getBytes(StandardCharsets.UTF_8));
39	            StringBuilder sb = new StringBuilder();
40	            for (int i = 0; i < 8; i++) {
41	                sb.append(String.format("%02X", digest[i]));
42	            }
43	            return sb.toString();
44	        }
45	        catch (NoSuchAlgorithmException e) {
46	            throw new IllegalStateException("SHA-256 not available", e);
47	        }
48	    }
49	}
